//! Hot-path field accessor code generation — design §24.2.
//!
//! Dynamic field access that goes "name → hash lookup → offset → type-erased
//! pointer" on every touch is slow. §24.2 asks for two cooperating fast paths,
//! both delivered here and generated by `#[derive(Accessors)]`
//! (see `prism_reflect_macros`):
//!
//! 1. **Typed direct accessors.** For every named field the derive emits a
//!    [`FieldAccessor`] holding the field's `offset_of` constant plus
//!    monomorphised `fn(&T) -> &dyn Reflect` / `fn(&mut T) -> &mut dyn Reflect`
//!    getters. These compile down to a direct field reference (a single
//!    offset load), with no per-access string hashing. [`FieldAccess`] wraps
//!    them in ergonomic `field`/`field_mut`/`get`/`set` helpers.
//!
//! 2. **Cached access plans.** [`AccessPlan`] resolves a dotted path such as
//!    `"transform.translation.x"` **once** against the reflected struct graph,
//!    caching it as a chain of field *indices* (the "offset chain" of the
//!    design). Every later navigation replays the chain with pure `field_at`
//!    index lookups — no string comparison, no hashing — so serialization /
//!    networking / editor code that hammers the same path on many values reuses
//!    one compiled plan.
//!
//! The crate is `#![forbid(unsafe_code)]`, so the generated getters navigate by
//! ordinary safe reference (`&value.field`), which the compiler lowers to the
//! same offset load a hand-written accessor would — the `offset_of` constant is
//! kept as descriptive metadata, never used for raw pointer arithmetic.

use crate::apply::ApplyError;
use crate::reflect::{Reflect, ReflectMut, ReflectRef};
use alloc::string::{String, ToString};
use alloc::vec::Vec;
use core::fmt;

/// A compiled, typed accessor for one named field of `T` (design §24.2).
///
/// The getters are plain `fn` pointers emitted by `#[derive(Accessors)]`; each
/// is a direct `&value.field` reference, so calling one is a single offset load
/// with no dynamic name lookup.
pub struct FieldAccessor<T> {
    name: &'static str,
    offset: usize,
    get: fn(&T) -> &dyn Reflect,
    get_mut: fn(&mut T) -> &mut dyn Reflect,
}

impl<T> FieldAccessor<T> {
    /// Build a field accessor from its name, byte offset, and generated
    /// getters.
    ///
    /// This is a `const fn` so the derive can bake a whole
    /// `&'static [FieldAccessor<T>]` table into the binary with no runtime
    /// construction.
    #[must_use]
    pub const fn new(
        name: &'static str,
        offset: usize,
        get: fn(&T) -> &dyn Reflect,
        get_mut: fn(&mut T) -> &mut dyn Reflect,
    ) -> Self {
        Self {
            name,
            offset,
            get,
            get_mut,
        }
    }

    /// The field name.
    #[must_use]
    pub const fn name(&self) -> &'static str {
        self.name
    }

    /// The field's byte offset within `T`, from [`core::mem::offset_of!`].
    #[must_use]
    pub const fn offset(&self) -> usize {
        self.offset
    }

    /// Borrow the field of `value` as `&dyn Reflect` via the generated getter.
    #[must_use]
    pub fn get<'a>(&self, value: &'a T) -> &'a dyn Reflect {
        (self.get)(value)
    }

    /// Mutably borrow the field of `value` via the generated getter.
    #[must_use]
    pub fn get_mut<'a>(&self, value: &'a mut T) -> &'a mut dyn Reflect {
        (self.get_mut)(value)
    }
}

impl<T> fmt::Debug for FieldAccessor<T> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("FieldAccessor")
            .field("name", &self.name)
            .field("offset", &self.offset)
            .finish_non_exhaustive()
    }
}

/// A type whose named fields have generated, typed accessors (design §24.2).
///
/// Derived with `#[derive(Accessors)]` for named-field structs. The associated
/// [`ACCESSORS`](FieldAccess::ACCESSORS) table is a compile-time constant, so
/// the ergonomic helpers below add no per-call allocation and resolve a field
/// name with at most one linear scan of the (typically tiny) field list.
pub trait FieldAccess: Reflect + Sized + 'static {
    /// The generated accessor table, in field declaration order.
    const ACCESSORS: &'static [FieldAccessor<Self>];

    /// Borrow the accessor table.
    #[must_use]
    fn accessors() -> &'static [FieldAccessor<Self>] {
        Self::ACCESSORS
    }

    /// Look up a field accessor by name.
    #[must_use]
    fn accessor(name: &str) -> Option<&'static FieldAccessor<Self>> {
        Self::ACCESSORS.iter().find(|a| a.name == name)
    }

    /// Resolve a field name to its index in [`ACCESSORS`](FieldAccess::ACCESSORS).
    ///
    /// Resolving once and reusing the index turns a repeated name lookup into a
    /// direct slice index.
    #[must_use]
    fn accessor_index(name: &str) -> Option<usize> {
        Self::ACCESSORS.iter().position(|a| a.name == name)
    }

    /// Borrow a field by name as `&dyn Reflect`.
    #[must_use]
    fn field(&self, name: &str) -> Option<&dyn Reflect> {
        Self::accessor(name).map(|a| a.get(self))
    }

    /// Mutably borrow a field by name as `&mut dyn Reflect`.
    #[must_use]
    fn field_mut(&mut self, name: &str) -> Option<&mut dyn Reflect> {
        let accessor = Self::accessor(name)?;
        Some(accessor.get_mut(self))
    }

    /// Borrow a field by name and downcast it to a concrete `F`.
    #[must_use]
    fn get_field<F: Reflect>(&self, name: &str) -> Option<&F> {
        self.field(name)?.downcast_ref::<F>()
    }

    /// Mutably borrow a field by name and downcast it to a concrete `F`.
    #[must_use]
    fn get_field_mut<F: Reflect>(&mut self, name: &str) -> Option<&mut F> {
        self.field_mut(name)?.downcast_mut::<F>()
    }

    /// Set a field by name by [`apply`](Reflect::apply)-ing `value` onto it.
    ///
    /// # Errors
    /// Returns [`AccessError::UnknownField`] when no field matches `name`, or
    /// [`AccessError::Apply`] when the value's type is incompatible with the
    /// field.
    fn set_field(&mut self, name: &str, value: &dyn Reflect) -> Result<(), AccessError> {
        let accessor = Self::accessor(name).ok_or_else(|| AccessError::UnknownField {
            type_name: core::any::type_name::<Self>(),
            field: name.to_string(),
        })?;
        accessor.get_mut(self).apply(value).map_err(AccessError::Apply)
    }
}

/// An error raised by [`FieldAccess`] setters or [`AccessPlan`] navigation.
#[derive(Debug, Clone, PartialEq, Eq)]
#[non_exhaustive]
pub enum AccessError {
    /// No field with the given name exists on the type.
    UnknownField {
        /// The owning type's name.
        type_name: &'static str,
        /// The field name that failed to resolve.
        field: String,
    },
    /// A path segment tried to descend through a value that is not a
    /// named-field struct.
    NotAStruct {
        /// The value's type name at the failing step.
        type_name: &'static str,
        /// The path segment being resolved.
        segment: String,
    },
    /// The path was empty, so there is nothing to navigate to.
    EmptyPath,
    /// Applying the new value onto the resolved field failed.
    Apply(ApplyError),
}

impl fmt::Display for AccessError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            AccessError::UnknownField { type_name, field } => {
                write!(f, "type `{type_name}` has no field `{field}`")
            }
            AccessError::NotAStruct { type_name, segment } => write!(
                f,
                "cannot descend into `{segment}`: `{type_name}` is not a named-field struct"
            ),
            AccessError::EmptyPath => write!(f, "cannot compile an empty access path"),
            AccessError::Apply(err) => write!(f, "failed to set field: {err}"),
        }
    }
}

impl std::error::Error for AccessError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            AccessError::Apply(err) => Some(err),
            _ => None,
        }
    }
}

/// A dotted field path resolved once into a cached chain of field indices
/// (design §24.2's "offset chain").
///
/// [`compile`](AccessPlan::compile) walks the reflected struct graph a single
/// time, turning each `.`-separated segment into the field's positional index.
/// [`get`](AccessPlan::get)/[`get_mut`](AccessPlan::get_mut) then replay the
/// chain with pure index lookups — no string comparison and no hashing — which
/// is the reuse the design calls for when the same path is accessed across many
/// values of the same type.
///
/// A plan is tied to the *shape* it was compiled against; replaying it on a
/// value of a different type simply fails the lookup and returns `None` rather
/// than misreading memory (navigation is entirely safe reference walking).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AccessPlan {
    path: String,
    steps: Vec<usize>,
}

impl AccessPlan {
    /// Compile `path` (e.g. `"transform.translation.x"`) against `root`,
    /// caching the resolved field-index chain for later reuse.
    ///
    /// # Errors
    /// Returns [`AccessError::EmptyPath`] for an empty path,
    /// [`AccessError::NotAStruct`] when a segment tries to descend through a
    /// non-struct value, or [`AccessError::UnknownField`] when a segment names
    /// a field that does not exist at that level.
    pub fn compile(root: &dyn Reflect, path: &str) -> Result<Self, AccessError> {
        let segments: Vec<&str> = path.split('.').filter(|s| !s.is_empty()).collect();
        if segments.is_empty() {
            return Err(AccessError::EmptyPath);
        }

        let mut steps = Vec::with_capacity(segments.len());
        let mut current: &dyn Reflect = root;
        for segment in segments {
            let ReflectRef::Struct(structure) = current.reflect_ref() else {
                return Err(AccessError::NotAStruct {
                    type_name: current.type_name(),
                    segment: segment.to_string(),
                });
            };
            let index = (0..structure.field_count())
                .find(|&i| structure.name_at(i) == Some(segment))
                .ok_or_else(|| AccessError::UnknownField {
                    type_name: current.type_name(),
                    field: segment.to_string(),
                })?;
            steps.push(index);
            current = structure
                .field_at(index)
                .expect("index came from field_count range");
        }

        Ok(Self {
            path: path.to_string(),
            steps,
        })
    }

    /// The original dotted path this plan was compiled from.
    #[must_use]
    pub fn path(&self) -> &str {
        &self.path
    }

    /// The cached field-index chain.
    #[must_use]
    pub fn steps(&self) -> &[usize] {
        &self.steps
    }

    /// Replay the cached chain to borrow the target field of `root`.
    ///
    /// Returns `None` if `root` has a different shape than the plan was
    /// compiled for (a step index is out of range or lands on a non-struct).
    #[must_use]
    pub fn get<'a>(&self, root: &'a dyn Reflect) -> Option<&'a dyn Reflect> {
        let mut current: &dyn Reflect = root;
        for &index in &self.steps {
            let ReflectRef::Struct(structure) = current.reflect_ref() else {
                return None;
            };
            current = structure.field_at(index)?;
        }
        Some(current)
    }

    /// Replay the cached chain to mutably borrow the target field of `root`.
    ///
    /// Returns `None` if `root` has a different shape than the plan was
    /// compiled for.
    #[must_use]
    pub fn get_mut<'a>(&self, root: &'a mut dyn Reflect) -> Option<&'a mut dyn Reflect> {
        let mut current: &mut dyn Reflect = root;
        for &index in &self.steps {
            let ReflectMut::Struct(structure) = current.reflect_mut() else {
                return None;
            };
            current = structure.field_at_mut(index)?;
        }
        Some(current)
    }

    /// Resolve the target field of `root` and [`apply`](Reflect::apply) `value`
    /// onto it.
    ///
    /// # Errors
    /// Returns [`AccessError::UnknownField`] when the plan does not resolve on
    /// `root`, or [`AccessError::Apply`] when the value is incompatible with the
    /// field.
    pub fn set(&self, root: &mut dyn Reflect, value: &dyn Reflect) -> Result<(), AccessError> {
        let target = self.get_mut(root).ok_or_else(|| AccessError::UnknownField {
            type_name: core::any::type_name::<AccessPlan>(),
            field: self.path.clone(),
        })?;
        target.apply(value).map_err(AccessError::Apply)
    }
}
